function IS_CALABI_YAU(h, d):
  for p in 0..d, q in 0..d:
    if h(p,q) != h(q,p): return false        # conjugation symmetry
    if h(p,q) != h(d-p, d-q): return false    # Serre duality
  for p in 0..d+1, q in 0..d+1:
    if (p>d or q>d) and h(p,q) != 0: return false  # finite support
  return true

